import base64, json
from elasticsearch import Elasticsearch

def fetch_page(es: Elasticsearch, index: str, cursor: str | None, size: int = 100):
    if cursor:
        state = json.loads(base64.urlsafe_b64decode(cursor))
        pit_id, search_after = state["pit_id"], state["sort"]
    else:
        pit = es.open_point_in_time(index=index, keep_alive="2m")
        pit_id, search_after = pit["id"], None

    body = {
        "size": size,
        "pit": {"id": pit_id, "keep_alive": "2m"},
        "track_total_hits": False,
        "sort": [{"updated_at": "desc"}, {"product_id": "asc"}],
    }
    if search_after:
        body["search_after"] = search_after

    resp = es.search(body=body)
    hits = resp["hits"]["hits"]
    next_cursor = None
    if len(hits) == size:
        next_state = {"pit_id": resp["pit_id"], "sort": hits[-1]["sort"]}
        next_cursor = base64.urlsafe_b64encode(json.dumps(next_state).encode()).decode()
    return hits, next_cursor

# Hybrid router: allow shallow page jumps up to 2000, enforce cursor beyond
MAX_OFFSET = 2000
def validate_pagination(offset: int, size: int, cursor: str | None):
    if cursor is None and (offset + size) > MAX_OFFSET:
        raise ValueError(f"Deep offset {offset + size} exceeds {MAX_OFFSET}; use cursor pagination.")

from elasticsearch import BadRequestError, NotFoundError

def safe_fetch_page(es, index, cursor, size=100):
    try:
        return fetch_page(es, index, cursor, size)
    except (BadRequestError, NotFoundError) as exc:
        if "search_context_missing_exception" in str(exc) and cursor:
            state = json.loads(base64.urlsafe_b64decode(cursor))
            fresh_pit = es.open_point_in_time(index=index, keep_alive="2m")["id"]
            rebuilt = base64.urlsafe_b64encode(json.dumps({"pit_id": fresh_pit, "sort": state["sort"]}).encode()).decode()
            return fetch_page(es, index, rebuilt, size)
        raise

def fetch_slice(es: Elasticsearch, pit_id: str, slice_id: int, max_slices: int, size: int = 500):
    search_after = None
    while True:
        body = {
            "size": size,
            "pit": {"id": pit_id, "keep_alive": "2m"},
            "slice": {"id": slice_id, "max": max_slices},
            "sort": [{"_shard_doc": "asc"}],
        }
        if search_after:
            body["search_after"] = search_after
        hits = es.search(body=body)["hits"]["hits"]
        if not hits:
            break
        yield hits
        search_after = hits[-1]["sort"]
